// 出生抽样来源独立codec；结构不完整或重名字段拒绝，不能回读时补抽或补亲代。
#include "birth_endowment.hpp"
#include "resident/domains/family/succession_personal_assets.hpp"
#include "resident/storage/common_checkpoint.hpp"
#include <set>
#include "family_extension_projection.hpp"
namespace hanmo::resident {namespace {
using V=BoundaryValue;
// 持久化原始字段顺序保完整唯一，允许新对象没有原JSON顺序。
bool order(const FieldOrder& value,const std::set<StableId>& keys){return value.empty()||(value.size()==keys.size()&&std::set<StableId>(value.begin(),value.end())==keys);}
Status shape(const InnateParentSource& p){std::set<StableId> keys;if(p.actor_id)keys.insert("actor_id");if(p.level)keys.insert("level");if(p.actor_id&&(p.actor_id->empty()||p.actor_id->size()>256))return common_failure("InvalidInnateParent");if(p.level&&(!p.actor_id||*p.level<0||*p.level>3))return common_failure("InvalidInnateParentLevel");return order(p.field_order,keys)?common_success():common_failure("BoundaryFieldOrderMismatch");}
Status shape(const BirthInnateResult& result){auto valid=shape(result.first);if(!valid.ok)return valid;valid=shape(result.second);if(!valid.ok)return valid;if(result.family_id.empty()||result.family_id.size()>256||result.policy_version!="innate_birth_v1"||result.draw<0||result.draw>=10000||result.level<0||result.level>3||(result.first.actor_id&&result.first.actor_id==result.second.actor_id))return common_failure("InvalidBirthInnateResult");const std::set<StableId> branches{"known_zero","unweighted_unknown","single_positive","different_positive","equal_positive"};return branches.count(result.branch)&&order(result.field_order,{"family_id","policy_version","first","second","branch","draw","level"})?common_success():common_failure("InvalidBirthInnateResult");}
// 每位亲代都是明确可选项，空对象保未知；null或缺失level不作0档替换。
InnateParentSource parent(const V& value){using namespace boundary;fields(value,{}, {"actor_id","level"},"innate/parent");InnateParentSource out;if(value.find("actor_id"))out.actor_id=get_string(value,"actor_id","");if(value.find("level"))out.level=get_int(value,"level","");out.field_order=boundary::order(value);auto valid=shape(out);if(!valid.ok)fail(valid.error.original.code,"innate/parent");return out;}
V encode_parent(const InnateParentSource& p){return family_projection::encode([&](auto& w){return emit_innate_parent_source_fields(w,p);});}
Status visit_parent(CodecVisitor& c,InnateParentSource& p){c.optional("actor_id",p.actor_id,[](CodecVisitor& at,StableId& value){return at.field("value",value);});c.optional("level",p.level,[](CodecVisitor& at,Integer& value){return at.field("value",value);});common_checkpoint::strings(c,"field_order",p.field_order);if(!c.status().ok)return c.status();auto valid=shape(p);return valid.ok?c.status():c.reject(valid.error.original.code);}
}
Outcome<BirthInnateResult> decode_birth_innate_result(const V& value){try{using namespace boundary;auto unique=validate_succession_json_unique(value);if(!unique.ok)return {false,{},unique.error};fields(value,{"family_id","policy_version","first","second","branch","draw","level"},{},"birth_innate");BirthInnateResult result;result.family_id=get_string(value,"family_id","");result.policy_version=get_string(value,"policy_version","");result.first=parent(field(value,"first",""));result.second=parent(field(value,"second",""));result.branch=get_string(value,"branch","");result.draw=get_int(value,"draw","");result.level=get_int(value,"level","");result.field_order=boundary::order(value);auto valid=shape(result);return valid.ok?Outcome<BirthInnateResult>{true,std::move(result),{}}:Outcome<BirthInnateResult>{false,{},valid.error};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status emit_innate_parent_source_fields(ProjectionWriter& w,const InnateParentSource& p){auto valid=shape(p);if(!valid.ok)return w.reject(valid.error.original.code,"innate/parent");if(p.actor_id)w.field("actor_id",*p.actor_id);if(p.level)w.field("level",*p.level);return w.order_fields(p.field_order);}
Status emit_birth_innate_result_fields(ProjectionWriter& w,const BirthInnateResult& result){auto valid=shape(result);if(!valid.ok)return w.reject(valid.error.original.code,"birth_innate");w.field("family_id",result.family_id);w.field("policy_version",result.policy_version);w.object("first",[&](auto& out){return emit_innate_parent_source_fields(out,result.first);});w.object("second",[&](auto& out){return emit_innate_parent_source_fields(out,result.second);});w.field("branch",result.branch);w.field("draw",result.draw);w.field("level",result.level);return w.order_fields(result.field_order);}
BoundaryValue encode_birth_innate_result(const BirthInnateResult& result){return family_projection::encode([&](auto& w){return emit_birth_innate_result_fields(w,result);});}
Status visit_birth_innate_result(CodecVisitor& c,BirthInnateResult& result){c.field("family_id",result.family_id);c.field("policy_version",result.policy_version);c.object("first",[&](CodecVisitor& at){return visit_parent(at,result.first);});c.object("second",[&](CodecVisitor& at){return visit_parent(at,result.second);});c.field("branch",result.branch);c.field("draw",result.draw);c.field("level",result.level);common_checkpoint::strings(c,"field_order",result.field_order);if(!c.status().ok)return c.status();auto valid=shape(result);return valid.ok?c.status():c.reject(valid.error.original.code);}
}
